551: kj::Promise<void> BackendImpl::downloadBackup(DownloadBackupContext context) {
552:   auto params = context.getParams();
553:   auto path = kj::str("/var/sandstorm/backups/", params.getBackupId());
554:   auto stream = params.getStream();
555:   context.releaseParams();
556: 
557:   auto fd = raiiOpen(path, O_RDONLY | O_CLOEXEC);
558:   struct stat stats;
559:   KJ_SYSCALL(fstat(fd, &stats));
560:   auto expectReq = stream.expectSizeRequest();
561:   expectReq.setSize(stats.st_size);
562:   auto expectPromise = expectReq.send();
563: 
564:   auto file = kj::heap<kj::FdInputStream>(kj::mv(fd));
565: 
566:   auto promise = pump(*file, kj::mv(stream));
567:   return promise.attach(kj::mv(file), kj::mv(expectPromise));
568: }
569: 
570: kj::Promise<void> BackendImpl::deleteBackup(DeleteBackupContext context) {
571:   auto path = kj::str("/var/sandstorm/backups/", context.getParams().getBackupId());
572:   while (unlink(path.cStr()) < 0) {
573:     int error = errno;
574:     if (error == ENOENT) {
575:       break;
576:     } else if (error != EINTR) {
577:       KJ_FAIL_SYSCALL("unlink", error, path);
578:     }
579:   }
580:   return kj::READY_NOW;

