190:     // searched).
191: 
192:     kj::ArrayPtr<const kj::StringPtr> argv;
193:     // Arguments to the program. By convention, the first argument should be the same as
194:     // `executable`.
195: 
196:     int stdin = STDIN_FILENO;
197:     int stdout = STDOUT_FILENO;
198:     int stderr = STDERR_FILENO;
199:     // What file descriptors to substitute for standard I/O.
200:     //
201:     // Note that if you override these, then the overridden FD is expected to be close-on-exec.
202:     // `Subprocess` does NOT close the old FD after dup2()ing it over the standard I/O FD.
203: 
204:     kj::ArrayPtr<int> moreFds;
205:     // You may pass additional FDs (3, 4, 5, 6, ...) using this array. `Subprocess` will
206:     // automatically deal with re-arranging file descriptors as needed, so if e.g. you pass in
207:     // the array {4, 3}, it will correctly swap the two descriptors. Again, it is expected that
208:     // all the file descriptors in this array (and indeed all file descriptors process-wide except
209:     // for 0, 1, and 2) are marked close-on-exec.
210: 
211:     kj::Maybe<kj::ArrayPtr<const kj::StringPtr>> environment;
212:     // An array of 'NAME=VALUE' pairs specifying the child's environment. If null, inherits the
213:     // parent's environment.
214: 
215:     Options(kj::StringPtr executable): executable(executable), argv(&this->executable, 1) {}
216:     Options(kj::ArrayPtr<const kj::StringPtr> argv): executable(argv[0]), argv(argv) {}
217:     Options(kj::Array<const kj::StringPtr>&& argv)
218:         : executable(argv[0]), argv(argv), ownArgv(kj::mv(argv)) {}
219:     Options(std::initializer_list<const kj::StringPtr> argv)
220:         : Options(kj::heapArray(argv)) {}
221: 
222:   private:
223:     kj::Array<const kj::StringPtr> ownArgv;
224:   };
225: 
226:   Subprocess(Options&& options);
227:   // Start a subprocess based on the given options.
228: 
229:   Subprocess(std::initializer_list<const kj::StringPtr> argv)
230:       : Subprocess(Options(kj::mv(argv))) {}
231:   // Start a subprocess given a simple command argument array. The first argument is the executable
232:   // name.
233: 
234:   Subprocess(kj::Function<int()> func);
235:   // Start a fork()ed subprocess that runs the given function then exits. Unlike the other
236:   // constructors, this constructor does not call exec()! Note that `func` is destroyed in the
237:   // parent process before this returns, since it is only needed in the child process. Note also
238:   // that under no circumstances will destructors of stack or global objects present before the
239:   // fork be executed inside the child process -- the child cannot unwind the stack with an
240:   // exception, and exits using _exit() to avoid global destructors.
241: 
242:   explicit Subprocess(pid_t pid): pid(pid) {}
243:   // Adopt a child process created by some other means.
244:   //
245:   // Be careful not to adopt a pid that has potentially already died and been reaped. Keep in mind
246:   // that if a SubprocessSet exists in the parent process then it is actively reaping childern at
247:   // all times. Remember than you can do kill(pid, 0) to check if the pid exists (although this is
248:   // problematic if it's been long enough that the kernel pid counter may have looped).
249: 
250:   KJ_DISALLOW_COPY(Subprocess);
