264: 
265:   int waitForExit() KJ_WARN_UNUSED_RESULT;
266:   // Waits for the child to exit and returns the exit status. Throws an exception if it is killed
267:   // by a signal.
268: 
269:   int waitForExitOrSignal() KJ_WARN_UNUSED_RESULT;
270:   // Waits for the child to exit or be killed by a signal. Returns an exit status that can be
