119: Router.map(function () {
120:   this.route("downloadBackup", {
121:     where: "server",
122:     path: "/downloadBackup/:tokenId",
123:     action: function () {
124:       var token = FileTokens.findOne(this.params.tokenId);
125:       var response = this.response;
126:       if (!token) {
127:         response.writeHead(404, {"Content-Type": "text/plain"});
128:         return response.end("File does not exist");
129:       }
130: 
131:       var started = false;
132:       var filename = (token.name.replace(/["\n]/g, "") || "backup") + ".zip";
133:       var sawEnd = false;
134: 
135:       var stream = {
136:         expectSize: function (size) {
137:           if (!started) {
138:             started = true;
139:             response.writeHead(200, {
140:               "Content-Length": size,
141:               "Content-Type": "application/zip",
142:               "Content-Disposition": "attachment;filename=\"" + filename + "\""
143:             });
144:           }
145:         },
146:         write: function (data) {
147:           if (!started) {
148:             started = true;
149:             response.writeHead(200, {
150:               "Content-Type": "application/zip",
151:               "Content-Disposition": "attachment;filename=\"" + filename + "\""
152:             });
153:           }
154:           response.write(data);
155:         },
156:         done: function (data) {
157:           if (!started) {
158:             started = true;
159:             response.writeHead(200, {
160:               "Content-Length": 0,
161:               "Content-Type": "application/zip",
162:               "Content-Disposition": "attachment;filename=\"" + filename + "\""
163:             });
164:           }
165:           sawEnd = true;
166:           response.end();
167:         }
168:       };
169: 
170:       waitPromise(sandstormBackend.downloadBackup(this.params.tokenId, stream));
171: 
172:       if (!sawEnd) {
173:         console.error("backend failed to call done() when downloading backup");
174:         if (!started) {
175:           throw new Meteor.Error(500, "backend failed to produce data");
176:         }
177:         response.end();
178:       }
179: 
180:       cleanupToken(this.params.tokenId);
181:     }
182:   });
183: 
184:   this.route("uploadBackup", {
185:     where: "server",
186:     path: "/uploadBackup",
187:     action: function () {
188:       if (this.request.method === "POST") {
189:         var request = this.request;
190:         try {
191:           var token = {
192:             _id: Random.id(),
193:             timestamp: new Date()
194:           };
195:           var stream = sandstormBackend.uploadBackup(token._id).stream;
196: 
197:           FileTokens.insert(token);
198: 
199:           waitPromise(new Promise(function (resolve, reject) {
200:             request.on("data", function (data) {
201:               stream.write(data);
202:             });
203:             request.on("end", function () {
204:               resolve(stream.done());
205:             });
206:             request.on("error", function (err) {
207:               stream.close();
208:             });
209:           }));
210: 
211:           this.response.writeHead(200, {
212:             "Content-Length": token._id.length,
213:             "Content-Type": "text/plain"
214:           });
215:           this.response.write(token._id);
216:           this.response.end();
217:         } catch(error) {
218:           console.error(error.stack);
219:           this.response.writeHead(500, {
220:             "Content-Type": "text/plain"
221:           });
222:           this.response.write(error.stack);
223:           this.response.end();
224:         }
225:       } else {
226:         this.response.writeHead(405, {
227:           "Content-Type": "text/plain"
228:         });
229:         this.response.write("You can only POST here.");
230:         this.response.end();
231:       }
232:     }
233:   });
234: });

