259: class BackendImpl::PackageUploadStreamImpl: public Backend::PackageUploadStream::Server {
260: public:
261:   PackageUploadStreamImpl(BackendImpl& backend, Pipe inPipe = Pipe::make(),
262:                           Pipe outPipe = Pipe::make())
263:       : inputWriteFd(kj::mv(inPipe.writeEnd)),
264:         outputReadFd(kj::mv(outPipe.readEnd)),
265:         inputWriteEnd(backend.ioProvider.wrapOutputFd(inputWriteFd,
266:             kj::LowLevelAsyncIoProvider::ALREADY_CLOEXEC)),
267:         outputReadEnd(backend.ioProvider.wrapInputFd(outputReadFd,
268:             kj::LowLevelAsyncIoProvider::ALREADY_CLOEXEC)),
269:         tmpdir(tempDirname()),
270:         unpackProcess(startProcess(kj::mv(inPipe.readEnd), kj::mv(outPipe.writeEnd), tmpdir)) {}
271:   ~PackageUploadStreamImpl() noexcept(false) {
272:     if (access(tmpdir.cStr(), F_OK) >= 0) {
273:       recursivelyDelete(tmpdir);
274:     }
275:   }
276: 
277: protected:
278:   kj::Promise<void> write(WriteContext context) override {
279:     auto forked = writeQueue.then([this,context]() mutable {
280:       auto data = context.getParams().getData();
281:       return KJ_REQUIRE_NONNULL(inputWriteEnd, "called write() after done()")
282:           ->write(data.begin(), data.size());
283:     }).fork();
284: 
285:     writeQueue = forked.addBranch();
286:     return forked.addBranch();
287:   }
288: 
289:   kj::Promise<void> done(DoneContext context) override {
290:     auto forked = writeQueue.then([this,context]() mutable {
291:       KJ_REQUIRE(inputWriteEnd != nullptr, "called done() multiple times");
292:       inputWriteEnd = nullptr;
293:       inputWriteFd = nullptr;
294:     }).fork();
295: 
296:     writeQueue = forked.addBranch();
297:     return forked.addBranch();
298:   }
299: 
300:   kj::Promise<void> expectSize(ExpectSizeContext context) override {
301:     // don't care
302:     return kj::READY_NOW;
303:   }
304: 
305:   kj::Promise<void> saveAs(SaveAsContext context) override {
306:     KJ_REQUIRE(!saveCalled, "saveAs() already called");
307:     saveCalled = true;
308:     return readAll(*outputReadEnd).then([this,context](kj::String text) mutable {
309:       unpackProcess.waitForSuccess();
310: 
311:       auto packageId = validateId(context.getParams().getPackageId());
312:       auto finalName = kj::str("/var/sandstorm/apps/", packageId);
313:       bool exists = access(finalName.cStr(), F_OK) >= 0;
314:       if (!exists) {
315:         // Write app ID file.
316:         kj::FdOutputStream(
317:             raiiOpen(kj::str(finalName, ".appid"), O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC))
318:             .write(text.begin(), text.size());
319: 
320:         // Move directory into place.
321:         KJ_SYSCALL(rename(tmpdir.cStr(), finalName.cStr()));
322:       }
323:       KJ_ON_SCOPE_FAILURE(if (!exists) { tryRecursivelyDelete(finalName); });
324: 
325:       capnp::StreamFdMessageReader reader(raiiOpen(
326:           kj::str(finalName, "/sandstorm-manifest"), O_RDONLY));
327:       auto manifest = reader.getRoot<spk::Manifest>();
328: 
329:       capnp::MessageSize sizeHint = manifest.totalSize();
330:       sizeHint.wordCount += 8 + text.size() / sizeof(capnp::word);
331:       auto results = context.getResults(sizeHint);
332:       results.setAppId(trim(text));
333:       results.setManifest(manifest);
334:     }, [this](kj::Exception&& e) {
335:       kj::runCatchingExceptions([&]() { recursivelyDelete(tmpdir); });
336:       kj::throwRecoverableException(kj::mv(e));
337:     });
338:   }
339: 
340: private:
341:   kj::AutoCloseFd inputWriteFd;
342:   kj::AutoCloseFd outputReadFd;
343:   kj::Maybe<kj::Own<kj::AsyncOutputStream>> inputWriteEnd;
344:   kj::Own<kj::AsyncInputStream> outputReadEnd;
345:   kj::Promise<void> writeQueue = kj::READY_NOW;
346:   kj::String tmpdir;
347:   Subprocess unpackProcess;
348:   bool saveCalled = false;
349: 
350:   static kj::String tempDirname() {
351:     static uint counter = 0;
352:     return kj::str("/var/sandstorm/tmp/unpacking.", time(nullptr), ".", counter++);
353:   }
354: 
355:   static Subprocess startProcess(
356:       kj::AutoCloseFd input, kj::AutoCloseFd output, kj::StringPtr outdir) {
357:     Subprocess::Options options({"spk", "unpack", "-", outdir});
358:     options.executable = "/proc/self/exe";
359:     options.stdin = input;
360:     options.stdout = output;
361:     return Subprocess(kj::mv(options));
362:   }
363: };
