428: kj::Promise<void> BackendImpl::restoreGrain(RestoreGrainContext context) {
429:   auto params = context.getParams();
430: 
431:   auto path = kj::str("/var/sandstorm/backups/", params.getBackupId());
432:   auto grainDir = kj::str("/var/sandstorm/grains/", params.getGrainId());
433:   KJ_SYSCALL(mkdir(grainDir.cStr(), 0777));
434:   Subprocess::Options processOptions({"backup", "-r", path, grainDir});
435:   processOptions.executable = "/proc/self/exe";
436:   auto outPipe = Pipe::make();
437:   processOptions.stdout = outPipe.writeEnd;
438:   Subprocess process(kj::mv(processOptions));
439:   outPipe.writeEnd = nullptr;
440: 
441:   context.releaseParams();
442: 
443:   auto input = kj::mv(outPipe.readEnd);
444:   auto asyncInput = ioProvider.wrapInputFd(input, kj::LowLevelAsyncIoProvider::ALREADY_CLOEXEC);
445: 
446:   auto promise = capnp::readMessage(*asyncInput);
447:   return promise.attach(kj::mv(input), kj::mv(asyncInput), kj::mv(process))
448:       .then([context](kj::Own<capnp::MessageReader>&& message) mutable {
449:     auto metadata = message->getRoot<GrainInfo>();
450:     context.getResults(capnp::MessageSize { metadata.totalSize().wordCount + 4, 0 })
451:         .setInfo(metadata);
452:   });
453: }
