455: class BackendImpl::FileUploadStream: public ByteStream::Server {
456: public:
457:   FileUploadStream(kj::String finalPath)
458:       : fd(raiiOpen(dirname(finalPath), O_WRONLY | O_TMPFILE)),
459:         finalPath(kj::mv(finalPath)) {}
460: 
461: protected:
462:   kj::Promise<void> write(WriteContext context) override {
463:     auto data = context.getParams().getData();
464:     kj::FdOutputStream(fd.get()).write(data.begin(), data.size());
465:     return kj::READY_NOW;
466:   }
467: 
468:   kj::Promise<void> done(DoneContext context) override {
469:     KJ_SYSCALL(fdatasync(fd));
470: 
471:     // Link temporary file into filesystem.
472:     KJ_SYSCALL(linkat(AT_FDCWD, kj::str("/proc/self/fd/", fd.get()).cStr(),
473:                       AT_FDCWD, finalPath.cStr(), AT_SYMLINK_FOLLOW));
474:     return kj::READY_NOW;
475:   }
476: 
477:   kj::Promise<void> expectSize(ExpectSizeContext context) override {
478:     // don't care
479:     return kj::READY_NOW;
480:   }
481: 
482: private:
483:   kj::AutoCloseFd fd;
484:   kj::String finalPath;
485: 
486:   static kj::String dirname(kj::StringPtr path) {
487:     KJ_IF_MAYBE(pos, path.findLast('/')) {
488:       return kj::heapString(path.slice(0, *pos));
489:     } else {
490:       return kj::heapString(".");
491:     }
492:   }
493: };
